KG42.register("nodes-4fd89cfc377ed0cbafaab0c0",{"id":"COMP-42adfdfb6dfa84b0","code":"BID008","label":"Supply-bid and schedule exemptions with neighboring regulation-bid inputs","definition":"This unit jointly contains two definitions: EcoGrid participants do not submit supply bids or schedules; the upward/downward regulation bid quantities and prices already submitted in the adjacent RP market serve as inputs to the TSO optimization. RP bids are submitted 45 minutes before the operating hour; their quantities set deployment upper limits, and their prices serve as regulation cost coefficients.","layer":"L3","template_code":"PGR","concept_id":"bidding.supply","concept_ids":["bidding.supply"],"identity_dimensions":{"identity_fields":["Object one: EcoGrid participants' supply bids and schedules; rule: no submission required","Object two: RP upward/downward regulation bid quantities and prices; rule: after submission, they serve as optimization inputs","Output: a non-submission requirement and submitted supply information belonging to different market scopes"]},"exclusions":["EcoGrid participants respond autonomously to the current price.","RP bid quantities: Pbar^{G,UR}_g, Pbar^{G,DR}_g","RP bid prices: λ^{G,UR}_g, λ^{G,DR}_g","RP submission time: 45 minutes before the operating hour, earlier than the publication of the real-time price for that hour","The bids are used in single-period or multi-period scenario models; the downward-regulation bid price carries a negative sign in the original regulation cost term."],"members":[{"id":"08-real_time_prices::v141-c-R002::V::bidding.supply","rule_id":"v141-c-R002","market_meaning":"Supply bid submission is not part of the EcoGrid EU real-time market. Scope: Supply submission in the EcoGrid EU bidless real-time market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Supply submission in the EcoGrid EU bidless real-time market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev18"]},"constraint_refs":["08-real_time_prices::v141-c-R002::v141-c-R002-C001","08-real_time_prices::v141-c-R002::v141-c-R002-C002"],"decision_anchor":"bidding.supply","source_rule_sha256":"870806b79a852dd48222c9c210f32799cc00d1822019efc9ac375624da7c42bf","paper":"08-real_time_prices","rule_ref":"08-real_time_prices::v141-c-R002","node_id":"bidding.supply","function":"bidding.supply","unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","mechanism_id":"v141-a-M01","anchor":true},{"id":"08-real_time_prices::v141-c-R003::V::bidding.supply","rule_id":"v141-c-R003","market_meaning":"Submitted up- and down-regulating bids, including quantities and prices, provide inputs to the social-welfare optimization. Scope: TSO optimization of the EcoGrid EU real-time market alongside the regulating power market. Submitted regulating-power quantities cap the up- and down-regulating deployment selected by the social-welfare optimization. Scope: Regulating-power deployment within the single-period and multi-period social-welfare optimization models. Condition: For each modeled generating unit and applicable time step and scenario. The objective is to minimize total social cost, equivalently maximize social welfare, accounting for regulating-power cost, demand and DER response, load-shedding costs and wind-spillage costs. Scope: Single-period social-welfare optimization for the next time step. Condition: When the single-period model is applied. The optimization objective is to maximize expected social welfare throughout the study horizon. Scope: Multi-period stochastic social-welfare optimization over the study horizon. Condition: When uncertain wind production and aggregated consumer and DER responses are represented by scenarios with occurrence probabilities. The modeled solution must satisfy the TSO's expected supply-demand balance, generating-unit ramp limits, and bounds on consumer and DER power. The balance constraint creates no physical or financial obligation for prosumers. Scope: Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. Condition: At the next time step, t = 1. Feasible modeled decisions must satisfy power balance, generating-unit ramp limits, and bounds on consumer and DER power in each applicable time period and scenario. Scope: Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. Condition: For modeled time steps from t = 2 through the study horizon, in each scenario.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. | Multi-period stochastic social-welfare optimization over the study horizon. | Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. | Regulating-power deployment within the single-period and multi-period social-welfare optimization models. | Single-period social-welfare optimization for the next time step. | TSO optimization of the EcoGrid EU real-time market alongside the regulating power market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev31","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"constraint_refs":["08-real_time_prices::v141-c-R003::v141-c-R003-C001","08-real_time_prices::v141-c-R003::v141-c-R003-C002","08-real_time_prices::v141-c-R003::v141-c-R003-C007"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"9ad64cf31832f7eb65c669c100f798fdd94f60898a124bc061022fe67e3404a7","paper":"08-real_time_prices","rule_ref":"08-real_time_prices::v141-c-R003","node_id":"bidding.supply","function":"bidding.supply","unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","mechanism_id":"v141-a-M01","anchor":false},{"id":"08-real_time_prices::v141-c-R004::V::bidding.supply","rule_id":"v141-c-R004","market_meaning":"RP supply bids are submitted 45 minutes before the operational hour, preceding announcement of the real-time price signals during that hour. Scope: Current RP bid-submission deadlines and EcoGrid real-time price announcements for the same operational hour. The social-welfare optimization determines the real-time price used for price-signal coordination at the next time step. Scope: Single-period TSO optimization for balancing at the next time step. Condition: When the proposed single-period optimization model is used. The optimization maximizing expected social welfare determines the real-time price and price forecasts for price-signal coordination. Scope: Proposed multi-period stochastic optimization over the study horizon. Condition: When the proposed multi-period stochastic optimization model is used. The real-time coordination price is set according to system operating status, reflecting balancing-power needs and/or transmission or distribution congestion. Scope: EcoGrid real-time price-setting design. The real-time coordination price equals the day-ahead spot price for the operational hour. Scope: EcoGrid real-time coordination price for an operational hour. Condition: No imbalance or congestion exists. The real-time coordination price is updated every five minutes. Scope: EcoGrid EU's specified five-minute market design. Real-time price-signal intervals must match smart-meter intervals. Scope: Alignment of price signals with measurement and settlement intervals. Condition: Electricity consumption or production is to be measured and settled for each market interval. The real-time price signal must be sent directly from the TSO-managed real-time marketplace to market participants. Scope: Delivery of EcoGrid real-time coordination prices. Published day-ahead spot-price signals are provided only to enable planning of next-day production or consumption; they are not used for prosumer response. Scope: Day-ahead spot-price signals published in the real-time marketplace for the following day. Condition: After the day-ahead spot market has settled. Short-term real-time price forecasts based on predicted balancing-power requirements may be delivered to participants to adjust their production or consumption plans. Scope: Short-term production and consumption planning by market participants. The real-time price signal for each five-minute interval is published before that interval starts. Scope: Publication of real-time signals during operation of the five-minute market. Participating prosumers may take actions according to the real-time electricity price at any time. Scope: Timing of decentralized actions responding to EcoGrid real-time prices. Receiving and responding to real-time prices does not impose physical or financial performance obligations on prosumers to fulfill the TSO's expected supply-demand balance. Scope: Price-responsive behavior represented in the proposed model's supply-demand balance constraint (2). The general real-time price signal applies only to small prosumers, such as households. Scope: Proposed anti-arbitrage rules separating RP and real-time market participation. Condition: If the TSO adopts the proposed market-separation rules. Timely communication of price signals must be ensured through flexible, scalable ICT infrastructure; availability of smart controllers that receive prices and control attached devices is assumed. Scope: Stated infrastructure prerequisites for implementing the proposed price-responsive market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Alignment of price signals with measurement and settlement intervals. | Current RP bid-submission deadlines and EcoGrid real-time price announcements for the same operational hour. | Day-ahead spot-price signals published in the real-time marketplace for the following day. | Delivery of EcoGrid real-time coordination prices. | EcoGrid EU's specified five-minute market design. | EcoGrid real-time coordination price for an operational hour. | EcoGrid real-time price-setting design. | Price-responsive behavior represented in the proposed model's supply-demand balance constraint (2). | Proposed anti-arbitrage rules separating RP and real-time market participation. | Proposed multi-period stochastic optimization over the study horizon. | Publication of real-time signals during operation of the five-minute market. | Short-term production and consumption planning by market participants. | Single-period TSO optimization for balancing at the next time step. | Stated infrastructure prerequisites for implementing the proposed price-responsive market. | Timing of decentralized actions responding to EcoGrid real-time prices.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev11","v141-b-g01-ev12","v141-b-g01-ev15","v141-b-g01-ev22","v141-b-g01-ev23","v141-b-g01-ev24","v141-b-g01-ev30","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-22","v141-b-g03-e10"]},"constraint_refs":["08-real_time_prices::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"f8777d8de826b85796fab451187de9a651de5742ca1e33865ada77862d5821ce","paper":"08-real_time_prices","rule_ref":"08-real_time_prices::v141-c-R004","node_id":"bidding.supply","function":"bidding.supply","unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["08-real_time_prices"],"evidence":[{"evidence_id":"v141-b-g01-ev18","location":{"location_id":"src-da8e4e26d6-p03-c1r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. REAL-TIME MARKET CONCEPT ARCHITECTURE","anchor_text":"interval can be further shortened, e.g., 1-min, which can achieve w better response for balancing se","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Ecogrid EU real-time market is a bidless electricity market: the submissions of plans and bid as known from existing electricity markets will not be part of the EcoGrid EU market [9]. It is in that sense a true real-time market, according to the definition in [5], which can greatly minimize the transactions costs of prosumers participating in the market because they simply respond to the current market price set by the market operator.","paper":"08-real_time_prices","rule_id":"v141-c-R002","quote":"The Ecogrid EU real-time market is a bidless electricity market: the submissions of plans and bid as known from existing electricity markets will not be part of the EcoGrid EU market [9]. It is in that sense a true real-time market, according to the definition in [5], which can greatly minimize the transactions costs of prosumers participating in the market because they simply respond to the current market price set by the market operator."},{"evidence_id":"v141-b-g01-ev31","location":{"location_id":"src-da8e4e26d6-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. OPTIMIZATION MODELS FOR REAL-TIME PRICE SETTLEMENT AND FORECAST","anchor_text":"tively small. With the increasing predication accuracy, the ratio can be gradually increased. In ord","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In order to implement the optimization model, the TSO has the following certain information: Cleared quantities to be generated and consumed as well as resulting prices from the day-ahead spot market. Up and down regulating bids (quantities and prices) submitted by generating units. Technical constraints of generating units such as maximum output and ramp limits. Moreover, the TSO has to make its decisions taking into consideration some uncertain parameters, such as: Power production of RESs, mainly wind production. Aggregated response of prosumers to real-time electricity prices. Taking into account both the known information and the uncertain parameters, the TSO has to determine: The deployment of up and down regulating power. The real-time electricity price and forecast to be sent to the market players.","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"In order to implement the optimization model, the TSO has the following certain information: Cleared quantities to be generated and consumed as well as resulting prices from the day-ahead spot market. Up and down regulating bids (quantities and prices) submitted by generating units. Technical constraints of generating units such as maximum output and ramp limits. Moreover, the TSO has to make its decisions taking into consideration some uncertain parameters, such as: Power production of RESs, mainly wind production. Aggregated response of prosumers to real-time electricity prices. Taking into account both the known information and the uncertain parameters, the TSO has to determine: The deployment of up and down regulating power. The real-time electricity price and forecast to be sent to the market players."},{"evidence_id":"v141-b-g02-ev-17","location":{"location_id":"src-da8e4e26d6-p06-c2r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"The objective function (3), shown at the bottom of the page, aims to minimize the regulating power c","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The TSO will use the following single-period optimization model for the deployment of up and down regulating power and determination of real-time price for maintaining the system balance for the next time step $(t = 1)$. The objective function (3), shown at the bottom of the page, aims to minimize the regulating power cost taking into account the prosumer' response (demand and DERs) to real-time price signals, which aims to minimize the total social cost (equivalent to maximization of social welfare). Note that the costs of load shedding and wind spillage are also considered. In the prosumer' response model, a linear correlation between the electricity consumption or generation of an aggregation of prosumers (consumers or DERs) and the real-time electricity price is considered, which have been used in most technical literature [10]–[12].","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"The TSO will use the following single-period optimization model for the deployment of up and down regulating power and determination of real-time price for maintaining the system balance for the next time step $(t = 1)$. The objective function (3), shown at the bottom of the page, aims to minimize the regulating power cost taking into account the prosumer' response (demand and DERs) to real-time price signals, which aims to minimize the total social cost (equivalent to maximization of social welfare). Note that the costs of load shedding and wind spillage are also considered. In the prosumer' response model, a linear correlation between the electricity consumption or generation of an aggregation of prosumers (consumers or DERs) and the real-time electricity price is considered, which have been used in most technical literature [10]–[12]."},{"evidence_id":"v141-b-g02-ev-21","location":{"location_id":"src-da8e4e26d6-p07-c1r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"q ( ) p g y tim large unit at next time step . Note that this power is equal to the scheduled genera","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power.","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power."},{"evidence_id":"v141-b-g02-ev-22","location":{"location_id":"src-da8e4e26d6-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"time step and price forecasts at time step is for different possible scenarios. The TSO also de- lus","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"In real life, only a real-time price signal for the next ﬁve minute may not be sufﬁcient for market players for scheduling their production or consumption in an optimal way. Short-term and accurate real-time price forecast (e.g., price forecast for the operational hour) based on the predicted requirements of balancing power can be delivered to market players for optimally adjusting their production or consumption planning. Inspired by that, a multi-period optimization model for determining real-time price and price forecast should also be developed. Uncertain parameters such as wind production and aggregated response of consumers and DERs to real-time electricity prices are approximated by a set of scenarios with their corresponding probabilities of occurrence. The TSO will use the following multi-period stochastic optimization model for determining the real-time price at the next time step $(t = 1)$ and price forecasts at time step $t(\\forall t = 2, \\ldots, N_t)$ for different possible scenarios. The TSO also determines the deployment of up and down regulating power at the next time step $(t = 1)$ and time step $t(\\forall t = 2, \\ldots, N_t)$ for all possible scenarios respectively. The objective function of the proposed model will then be the maximization of the expected social welfare throughout the study horizon, i.e., the minimization of the reserve deployment cost by the generators and DERs for providing balancing power plus wind spillage cost minus the utility losses of the consumers. As shown in (14) at the bottom of the page, the objective function includes two items. The ﬁrst item represents the corresponding cost at next time step $(t = 1)$, which is the same as (4). The second item represents the expected cost incurred from time step $t = 2$ to time step $t = N_t$. The objective function (14) is subject to constraints (2), (4)–(13) and following constraints:","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"In real life, only a real-time price signal for the next ﬁve minute may not be sufﬁcient for market players for scheduling their production or consumption in an optimal way. Short-term and accurate real-time price forecast (e.g., price forecast for the operational hour) based on the predicted requirements of balancing power can be delivered to market players for optimally adjusting their production or consumption planning. Inspired by that, a multi-period optimization model for determining real-time price and price forecast should also be developed. Uncertain parameters such as wind production and aggregated response of consumers and DERs to real-time electricity prices are approximated by a set of scenarios with their corresponding probabilities of occurrence. The TSO will use the following multi-period stochastic optimization model for determining the real-time price at the next time step $(t = 1)$ and price forecasts at time step $t(\\forall t = 2, \\ldots, N_t)$ for different possible scenarios. The TSO also determines the deployment of up and down regulating power at the next time step $(t = 1)$ and time step $t(\\forall t = 2, \\ldots, N_t)$ for all possible scenarios respectively. The objective function of the proposed model will then be the maximization of the expected social welfare throughout the study horizon, i.e., the minimization of the reserve deployment cost by the generators and DERs for providing balancing power plus wind spillage cost minus the utility losses of the consumers. As shown in (14) at the bottom of the page, the objective function includes two items. The ﬁrst item represents the corresponding cost at next time step $(t = 1)$, which is the same as (4). The second item represents the expected cost incurred from time step $t = 2$ to time step $t = N_t$. The objective function (14) is subject to constraints (2), (4)–(13) and following constraints:"},{"evidence_id":"v141-b-g02-ev-24","location":{"location_id":"src-da8e4e26d6-p07-c2r3__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"ial me (15) he ost ve ng rm the (16) al- lly (17)","equation_id":"Eq. (15)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,t,s)} = P^{G,D}_{g} + P^{G,UR}_{(g,t,s)} - P^{G,DR}_{(g,t,s)}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (15)\n$\\sum_{l}^{N_L} (P^{L}_{(l,t,s)} + \\Delta P^{L}_{(l,t,s)} - L^{Shed}_{(l,t,s)}) - \\sum_{g}^{N_G} P^{G}_{(g,t,s)} - \\sum_{d}^{N_{DER}} (P^{DER}_{(d,t,s)} + \\Delta P^{DER}_{(d,t,s)}) - \\sum_{w}^{N_W} (P^{W}_{(w,t,s)} - W^{Spill}_{(w,t,s)}) = 0, \\forall t = 2, \\ldots, N_t, \\forall s$  (16)\n$0 \\le P^{G,UR}_{(g,t,s)} \\le \\overline{P^{G,UR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (17)","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"$P^{G}_{(g,t,s)} = P^{G,D}_{g} + P^{G,UR}_{(g,t,s)} - P^{G,DR}_{(g,t,s)}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (15)\n$\\sum_{l}^{N_L} (P^{L}_{(l,t,s)} + \\Delta P^{L}_{(l,t,s)} - L^{Shed}_{(l,t,s)}) - \\sum_{g}^{N_G} P^{G}_{(g,t,s)} - \\sum_{d}^{N_{DER}} (P^{DER}_{(d,t,s)} + \\Delta P^{DER}_{(d,t,s)}) - \\sum_{w}^{N_W} (P^{W}_{(w,t,s)} - W^{Spill}_{(w,t,s)}) = 0, \\forall t = 2, \\ldots, N_t, \\forall s$  (16)\n$0 \\le P^{G,UR}_{(g,t,s)} \\le \\overline{P^{G,UR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (17)"},{"evidence_id":"v141-b-g02-ev-25","location":{"location_id":"src-da8e4e26d6-p08-c1r1__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"DING et al.: REAL-TIME MARKET CONCEPT ARCHITECTURE (18) (19) (20) (21) (22)","equation_id":"Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"$0 \\le P^{G,DR}_{(g,t,s)} \\le \\overline{P^{G,DR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (18)\n$P^{G}_{(g,t-1,s)} - DR_{g} \\le P^{G}_{(g,t,s)} \\le P^{G}_{(g,t-1,s)} + UR_{g}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (19)\n$-\\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (20)\n$\\alpha_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall d, \\forall t = 2, \\ldots, N_t, \\forall s$  (21)\n$P^{L,min}_{(l,t)} \\le P^{L}_{(l,t)} + \\Delta P^{L}_{(l,t,s)} \\le P^{L,max}_{(l,t)}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (22)","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"$0 \\le P^{G,DR}_{(g,t,s)} \\le \\overline{P^{G,DR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (18)\n$P^{G}_{(g,t-1,s)} - DR_{g} \\le P^{G}_{(g,t,s)} \\le P^{G}_{(g,t-1,s)} + UR_{g}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (19)\n$-\\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (20)\n$\\alpha_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall d, \\forall t = 2, \\ldots, N_t, \\forall s$  (21)\n$P^{L,min}_{(l,t)} \\le P^{L}_{(l,t)} + \\Delta P^{L}_{(l,t,s)} \\le P^{L,max}_{(l,t)}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (22)"},{"evidence_id":"v141-b-g02-ev-27","location":{"location_id":"src-da8e4e26d6-p08-c1r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"V. Quantitative Analyses","anchor_text":"p y price variations is described through (20) and (21) respectively. Likewise, the maximum and mini","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"unknown"},"source_text":"Equation (15) determines the total power produced by each large generating unit, time period and scenario. The power balance at each time period and scenario is enforced through (16). Constraints (17) and (18) limit the maximum deployment of up and down regulating power at each time period and scenario. The generating unit ramps bound the power generated at each time period and scenario through constraint (19). The response of consumers and DERs to real-time electricity price variations is described through (20) and (21) respectively. Likewise, the maximum and minimum changes of the consumers and DER's are imposed through constraints (22) and (23). Constraints (24) and (25) are positive variable declarations. By solving the above optimization problem, we can obtain real time prices, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power at each time period for different scenarios.","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"Equation (15) determines the total power produced by each large generating unit, time period and scenario. The power balance at each time period and scenario is enforced through (16). Constraints (17) and (18) limit the maximum deployment of up and down regulating power at each time period and scenario. The generating unit ramps bound the power generated at each time period and scenario through constraint (19). The response of consumers and DERs to real-time electricity price variations is described through (20) and (21) respectively. Likewise, the maximum and minimum changes of the consumers and DER's are imposed through constraints (22) and (23). Constraints (24) and (25) are positive variable declarations. By solving the above optimization problem, we can obtain real time prices, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power at each time period for different scenarios."},{"evidence_id":"v141-b-g02-ev-19","location":{"location_id":"src-da8e4e26d6-p06-c2r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"The objective function (3), shown at the bottom of the page, aims to minimize the regulating power c","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,1)} = P^{G,D}_{g} + P^{G,UR}_{(g,1)} - P^{G,DR}_{(g,1)}, \\forall g$  (4)\n$0 \\le P^{G,UR}_{(g,1)} \\le \\overline{P^{G,UR}_{g}}, \\forall g$  (5)\n$0 \\le P^{G,DR}_{(g,1)} \\le \\overline{P^{G,DR}_{g}}, \\forall g$  (6)\n$P^{G}_{(g,0)} - DR_{g} \\le P^{G}_{(g,1)} \\le P^{G}_{(g,0)} + UR_{g}, \\forall g$  (7)","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"$P^{G}_{(g,1)} = P^{G,D}_{g} + P^{G,UR}_{(g,1)} - P^{G,DR}_{(g,1)}, \\forall g$  (4)\n$0 \\le P^{G,UR}_{(g,1)} \\le \\overline{P^{G,UR}_{g}}, \\forall g$  (5)\n$0 \\le P^{G,DR}_{(g,1)} \\le \\overline{P^{G,DR}_{g}}, \\forall g$  (6)\n$P^{G}_{(g,0)} - DR_{g} \\le P^{G}_{(g,1)} \\le P^{G}_{(g,0)} + UR_{g}, \\forall g$  (7)"},{"evidence_id":"v141-b-g01-ev04","location":{"location_id":"src-da8e4e26d6-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"NOMENCLATURE","anchor_text":"Number of wind farms op- on- Number of scenarios to Constants ets ow Scheduled generated power of un","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Constants: P^{G,D}_{g} Scheduled generated power of unit g in the day-ahead market (MW); \\bar{P}^{G,UR}_{g} Up-regulating power offered by unit g (MW); \\bar{P}^{G,DR}_{g} Down-regulating power offered by unit g (MW); \\lambda^{G,UR}_{g} Bidding cost of electricity for up-regulation of unit g (euros/MWh); \\lambda^{G,DR}_{g} Bidding cost of electricity for down-regulation of unit g (euros/MWh); V^{LOL}_{l} Value of load shed corresponding to load l (euros/MWh); V^{spill}_{w} Value of wind spillage of wind farm w (euros/MWh); UR_{g} Up-ramp of generating unit g (MW/h); DR_{g} Down-ramp of generating unit g (MW/h).","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"Constants: P^{G,D}_{g} Scheduled generated power of unit g in the day-ahead market (MW); \\bar{P}^{G,UR}_{g} Up-regulating power offered by unit g (MW); \\bar{P}^{G,DR}_{g} Down-regulating power offered by unit g (MW); \\lambda^{G,UR}_{g} Bidding cost of electricity for up-regulation of unit g (euros/MWh); \\lambda^{G,DR}_{g} Bidding cost of electricity for down-regulation of unit g (euros/MWh); V^{LOL}_{l} Value of load shed corresponding to load l (euros/MWh); V^{spill}_{w} Value of wind spillage of wind farm w (euros/MWh); UR_{g} Up-ramp of generating unit g (MW/h); DR_{g} Down-ramp of generating unit g (MW/h)."},{"evidence_id":"v141-b-g02-ev-18","location":{"location_id":"src-da8e4e26d6-p06-c2r4__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"(5) (6) (7) (3) wnloaded on October 14,2026 at 08:46:10 UTC from IEEE Xplore. Restrictions apply.","equation_id":"Eq. (3)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{DER}_{(d,1)}, L^{Shed}_{(l,1)}, W^{Spill}_{(w,1)}, \\lambda^{R}_{1}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\}$  (3)","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{DER}_{(d,1)}, L^{Shed}_{(l,1)}, W^{Spill}_{(w,1)}, \\lambda^{R}_{1}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\}$  (3)"},{"evidence_id":"v141-b-g02-ev-23","location":{"location_id":"src-da8e4e26d6-p07-c2r4__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"(14) wnloaded on October 14,2026 at 08:46:10 UTC from IEEE Xplore. Restrictions apply.","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, P^{G,UR}_{(g,t,s)}, P^{G,DR}_{(g,t,s)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{L}_{(l,t,s)}, \\Delta P^{DER}_{(d,1)}, \\Delta P^{DER}_{(d,t,s)}, L^{Shed}_{(l,1)}, L^{Shed}_{(l,t,s)}, W^{Spill}_{(w,1)}, W^{Spill}_{(w,t,s)}, \\lambda^{R}_{1}, \\lambda^{R}_{(t,s)}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\} + \\sum_{s}^{N_S} \\sum_{t=2}^{N_t} \\pi_{s} \\cdot \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,t,s)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,t,s)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,t,s)} + \\frac{1}{2} \\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,t,s)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,t,s)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,t,s)} \\right\\}$  (14)","paper":"08-real_time_prices","rule_id":"v141-c-R003","quote":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, P^{G,UR}_{(g,t,s)}, P^{G,DR}_{(g,t,s)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{L}_{(l,t,s)}, \\Delta P^{DER}_{(d,1)}, \\Delta P^{DER}_{(d,t,s)}, L^{Shed}_{(l,1)}, L^{Shed}_{(l,t,s)}, W^{Spill}_{(w,1)}, W^{Spill}_{(w,t,s)}, \\lambda^{R}_{1}, \\lambda^{R}_{(t,s)}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\} + \\sum_{s}^{N_S} \\sum_{t=2}^{N_t} \\pi_{s} \\cdot \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,t,s)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,t,s)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,t,s)} + \\frac{1}{2} \\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,t,s)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,t,s)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,t,s)} \\right\\}$  (14)"},{"evidence_id":"v141-b-g01-ev30","location":{"location_id":"src-da8e4e26d6-p05-c1r4__v141-a-M02-participation","page":5,"printed_page":null,"section":"IV. OPTIMIZATION MODELS FOR REAL-TIME PRICE SETTLEMENT AND FORECAST","anchor_text":"market and the existing RP market can provide arbitrage oppor- ta tunities. It is possible that the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"exception"},"source_text":"To prevent price arbitrage between two markets, the TSO can set up market rules so that market players can only participate in only one market: RP market or real-time market. Specific market rules can be defined: The RP market addresses larger conventional generating units (above 10 MW). Only small prosumers e.g., households are subject to the general real-time price signal and participate in the real-time market. Moreover this problem would to a certain extent be mitigated by the current market rules: For participating in the RP market, the players (bulk physical suppliers) must submit their bids 45 mins before the operational hour. While real-time price signals are announced during the operational hour based on the system operational status, therefore it is not possible to use this information for create the bids in the RP market.","paper":"08-real_time_prices","rule_id":"v141-c-R004","quote":"To prevent price arbitrage between two markets, the TSO can set up market rules so that market players can only participate in only one market: RP market or real-time market. Specific market rules can be defined: The RP market addresses larger conventional generating units (above 10 MW). Only small prosumers e.g., households are subject to the general real-time price signal and participate in the real-time market. Moreover this problem would to a certain extent be mitigated by the current market rules: For participating in the RP market, the players (bulk physical suppliers) must submit their bids 45 mins before the operational hour. While real-time price signals are announced during the operational hour based on the system operational status, therefore it is not possible to use this information for create the bids in the RP market."}],"candidate_only":true,"classification_subtypes":["scoped_supply_submission_rules"],"projection_statuses":["composite"],"taxonomy":{"primary_family":"kind-L3-c90fc916e3","secondary_families":[],"stage":"L3","ontological_kind":"composite_rule"},"semantic_definition":{},"source_units":[{"unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","paper_id":"08-real_time_prices","mechanism_id":"v141-a-M01","function":"bidding.supply","source_occurrences":[{"id":"08-real_time_prices::v141-c-R002::V::bidding.supply","rule_id":"v141-c-R002","market_meaning":"Supply bid submission is not part of the EcoGrid EU real-time market. Scope: Supply submission in the EcoGrid EU bidless real-time market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Supply submission in the EcoGrid EU bidless real-time market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev18"]},"constraint_refs":["08-real_time_prices::v141-c-R002::v141-c-R002-C001","08-real_time_prices::v141-c-R002::v141-c-R002-C002"],"decision_anchor":"bidding.supply","source_rule_sha256":"870806b79a852dd48222c9c210f32799cc00d1822019efc9ac375624da7c42bf"},{"id":"08-real_time_prices::v141-c-R003::V::bidding.supply","rule_id":"v141-c-R003","market_meaning":"Submitted up- and down-regulating bids, including quantities and prices, provide inputs to the social-welfare optimization. Scope: TSO optimization of the EcoGrid EU real-time market alongside the regulating power market. Submitted regulating-power quantities cap the up- and down-regulating deployment selected by the social-welfare optimization. Scope: Regulating-power deployment within the single-period and multi-period social-welfare optimization models. Condition: For each modeled generating unit and applicable time step and scenario. The objective is to minimize total social cost, equivalently maximize social welfare, accounting for regulating-power cost, demand and DER response, load-shedding costs and wind-spillage costs. Scope: Single-period social-welfare optimization for the next time step. Condition: When the single-period model is applied. The optimization objective is to maximize expected social welfare throughout the study horizon. Scope: Multi-period stochastic social-welfare optimization over the study horizon. Condition: When uncertain wind production and aggregated consumer and DER responses are represented by scenarios with occurrence probabilities. The modeled solution must satisfy the TSO's expected supply-demand balance, generating-unit ramp limits, and bounds on consumer and DER power. The balance constraint creates no physical or financial obligation for prosumers. Scope: Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. Condition: At the next time step, t = 1. Feasible modeled decisions must satisfy power balance, generating-unit ramp limits, and bounds on consumer and DER power in each applicable time period and scenario. Scope: Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. Condition: For modeled time steps from t = 2 through the study horizon, in each scenario.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Future-period feasibility constraints in the multi-period stochastic social-welfare optimization. | Multi-period stochastic social-welfare optimization over the study horizon. | Next-step feasibility constraints in the single-period model and the next-step component of the multi-period model. | Regulating-power deployment within the single-period and multi-period social-welfare optimization models. | Single-period social-welfare optimization for the next time step. | TSO optimization of the EcoGrid EU real-time market alongside the regulating power market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev31","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27"]},"constraint_refs":["08-real_time_prices::v141-c-R003::v141-c-R003-C001","08-real_time_prices::v141-c-R003::v141-c-R003-C002","08-real_time_prices::v141-c-R003::v141-c-R003-C007"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"9ad64cf31832f7eb65c669c100f798fdd94f60898a124bc061022fe67e3404a7"},{"id":"08-real_time_prices::v141-c-R004::V::bidding.supply","rule_id":"v141-c-R004","market_meaning":"RP supply bids are submitted 45 minutes before the operational hour, preceding announcement of the real-time price signals during that hour. Scope: Current RP bid-submission deadlines and EcoGrid real-time price announcements for the same operational hour. The social-welfare optimization determines the real-time price used for price-signal coordination at the next time step. Scope: Single-period TSO optimization for balancing at the next time step. Condition: When the proposed single-period optimization model is used. The optimization maximizing expected social welfare determines the real-time price and price forecasts for price-signal coordination. Scope: Proposed multi-period stochastic optimization over the study horizon. Condition: When the proposed multi-period stochastic optimization model is used. The real-time coordination price is set according to system operating status, reflecting balancing-power needs and/or transmission or distribution congestion. Scope: EcoGrid real-time price-setting design. The real-time coordination price equals the day-ahead spot price for the operational hour. Scope: EcoGrid real-time coordination price for an operational hour. Condition: No imbalance or congestion exists. The real-time coordination price is updated every five minutes. Scope: EcoGrid EU's specified five-minute market design. Real-time price-signal intervals must match smart-meter intervals. Scope: Alignment of price signals with measurement and settlement intervals. Condition: Electricity consumption or production is to be measured and settled for each market interval. The real-time price signal must be sent directly from the TSO-managed real-time marketplace to market participants. Scope: Delivery of EcoGrid real-time coordination prices. Published day-ahead spot-price signals are provided only to enable planning of next-day production or consumption; they are not used for prosumer response. Scope: Day-ahead spot-price signals published in the real-time marketplace for the following day. Condition: After the day-ahead spot market has settled. Short-term real-time price forecasts based on predicted balancing-power requirements may be delivered to participants to adjust their production or consumption plans. Scope: Short-term production and consumption planning by market participants. The real-time price signal for each five-minute interval is published before that interval starts. Scope: Publication of real-time signals during operation of the five-minute market. Participating prosumers may take actions according to the real-time electricity price at any time. Scope: Timing of decentralized actions responding to EcoGrid real-time prices. Receiving and responding to real-time prices does not impose physical or financial performance obligations on prosumers to fulfill the TSO's expected supply-demand balance. Scope: Price-responsive behavior represented in the proposed model's supply-demand balance constraint (2). The general real-time price signal applies only to small prosumers, such as households. Scope: Proposed anti-arbitrage rules separating RP and real-time market participation. Condition: If the TSO adopts the proposed market-separation rules. Timely communication of price signals must be ensured through flexible, scalable ICT infrastructure; availability of smart controllers that receive prices and control attached devices is assumed. Scope: Stated infrastructure prerequisites for implementing the proposed price-responsive market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Alignment of price signals with measurement and settlement intervals. | Current RP bid-submission deadlines and EcoGrid real-time price announcements for the same operational hour. | Day-ahead spot-price signals published in the real-time marketplace for the following day. | Delivery of EcoGrid real-time coordination prices. | EcoGrid EU's specified five-minute market design. | EcoGrid real-time coordination price for an operational hour. | EcoGrid real-time price-setting design. | Price-responsive behavior represented in the proposed model's supply-demand balance constraint (2). | Proposed anti-arbitrage rules separating RP and real-time market participation. | Proposed multi-period stochastic optimization over the study horizon. | Publication of real-time signals during operation of the five-minute market. | Short-term production and consumption planning by market participants. | Single-period TSO optimization for balancing at the next time step. | Stated infrastructure prerequisites for implementing the proposed price-responsive market. | Timing of decentralized actions responding to EcoGrid real-time prices.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev11","v141-b-g01-ev12","v141-b-g01-ev15","v141-b-g01-ev22","v141-b-g01-ev23","v141-b-g01-ev24","v141-b-g01-ev30","v141-b-g02-ev-16","v141-b-g02-ev-17","v141-b-g02-ev-22","v141-b-g03-e10"]},"constraint_refs":["08-real_time_prices::v141-c-R004::v141-c-R004-C001"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"f8777d8de826b85796fab451187de9a651de5742ca1e33865ada77862d5821ce"}],"constraints":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"Supply bid submission is not part of the EcoGrid EU real-time market. Scope: Supply submission in the EcoGrid EU bidless real-time market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev18"],"ref":"08-real_time_prices::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-ev18","location":{"location_id":"src-da8e4e26d6-p03-c1r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. REAL-TIME MARKET CONCEPT ARCHITECTURE","anchor_text":"interval can be further shortened, e.g., 1-min, which can achieve w better response for balancing se","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Ecogrid EU real-time market is a bidless electricity market: the submissions of plans and bid as known from existing electricity markets will not be part of the EcoGrid EU market [9]. It is in that sense a true real-time market, according to the definition in [5], which can greatly minimize the transactions costs of prosumers participating in the market because they simply respond to the current market price set by the market operator."}]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"supporting","statement":"Because the EcoGrid EU real-time market is bidless, market participants (prosumers) do not submit supply bids or plans but instead simply respond to the current market price set by the market operator. Scope: Supply submission in the EcoGrid EU bidless real-time market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev18"],"ref":"08-real_time_prices::v141-c-R002::v141-c-R002-C002","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-ev18","location":{"location_id":"src-da8e4e26d6-p03-c1r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. REAL-TIME MARKET CONCEPT ARCHITECTURE","anchor_text":"interval can be further shortened, e.g., 1-min, which can achieve w better response for balancing se","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Ecogrid EU real-time market is a bidless electricity market: the submissions of plans and bid as known from existing electricity markets will not be part of the EcoGrid EU market [9]. It is in that sense a true real-time market, according to the definition in [5], which can greatly minimize the transactions costs of prosumers participating in the market because they simply respond to the current market price set by the market operator."}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Submitted up- and down-regulating bids, including quantities and prices, provide inputs to the social-welfare optimization. Scope: TSO optimization of the EcoGrid EU real-time market alongside the regulating power market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev31","v141-b-g02-ev-17","v141-b-g02-ev-21"],"ref":"08-real_time_prices::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-ev31","location":{"location_id":"src-da8e4e26d6-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. OPTIMIZATION MODELS FOR REAL-TIME PRICE SETTLEMENT AND FORECAST","anchor_text":"tively small. With the increasing predication accuracy, the ratio can be gradually increased. In ord","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In order to implement the optimization model, the TSO has the following certain information: Cleared quantities to be generated and consumed as well as resulting prices from the day-ahead spot market. Up and down regulating bids (quantities and prices) submitted by generating units. Technical constraints of generating units such as maximum output and ramp limits. Moreover, the TSO has to make its decisions taking into consideration some uncertain parameters, such as: Power production of RESs, mainly wind production. Aggregated response of prosumers to real-time electricity prices. Taking into account both the known information and the uncertain parameters, the TSO has to determine: The deployment of up and down regulating power. The real-time electricity price and forecast to be sent to the market players."},{"evidence_id":"v141-b-g02-ev-17","location":{"location_id":"src-da8e4e26d6-p06-c2r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"The objective function (3), shown at the bottom of the page, aims to minimize the regulating power c","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The TSO will use the following single-period optimization model for the deployment of up and down regulating power and determination of real-time price for maintaining the system balance for the next time step $(t = 1)$. The objective function (3), shown at the bottom of the page, aims to minimize the regulating power cost taking into account the prosumer' response (demand and DERs) to real-time price signals, which aims to minimize the total social cost (equivalent to maximization of social welfare). Note that the costs of load shedding and wind spillage are also considered. In the prosumer' response model, a linear correlation between the electricity consumption or generation of an aggregation of prosumers (consumers or DERs) and the real-time electricity price is considered, which have been used in most technical literature [10]–[12]."},{"evidence_id":"v141-b-g02-ev-21","location":{"location_id":"src-da8e4e26d6-p07-c1r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"q ( ) p g y tim large unit at next time step . Note that this power is equal to the scheduled genera","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power."}]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"Submitted regulating-power quantities cap the up- and down-regulating deployment selected by the social-welfare optimization. Scope: Regulating-power deployment within the single-period and multi-period social-welfare optimization models. Condition: For each modeled generating unit and applicable time step and scenario.","expression":"0 ≤ P^{G,UR}_{(g,1)} ≤ Pbar^{G,UR}_{g}, ∀g  (5)\n0 ≤ P^{G,DR}_{(g,1)} ≤ Pbar^{G,DR}_{g}, ∀g  (6)\n0 ≤ P^{G,UR}_{(g,t,s)} ≤ Pbar^{G,UR}_{g}, ∀g, ∀t = 2,...,N_t, ∀s  (17)\n0 ≤ P^{G,DR}_{(g,t,s)} ≤ Pbar^{G,DR}_{g}, ∀g, ∀t = 2,...,N_t, ∀s  (18)","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R003-x-PGUR","v141-c-R003-x-PGDR"],"parameter_refs":["v141-c-R003-theta-PGUR-bar","v141-c-R003-theta-PGDR-bar"],"evidence_ids":["v141-b-g02-ev-21","v141-b-g02-ev-22","v141-b-g02-ev-24","v141-b-g02-ev-25","v141-b-g02-ev-27","v141-b-g02-ev-19","v141-b-g01-ev04"],"ref":"08-real_time_prices::v141-c-R003::v141-c-R003-C002","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-ev-21","location":{"location_id":"src-da8e4e26d6-p07-c1r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"q ( ) p g y tim large unit at next time step . Note that this power is equal to the scheduled genera","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power."},{"evidence_id":"v141-b-g02-ev-22","location":{"location_id":"src-da8e4e26d6-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"time step and price forecasts at time step is for different possible scenarios. The TSO also de- lus","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"In real life, only a real-time price signal for the next ﬁve minute may not be sufﬁcient for market players for scheduling their production or consumption in an optimal way. Short-term and accurate real-time price forecast (e.g., price forecast for the operational hour) based on the predicted requirements of balancing power can be delivered to market players for optimally adjusting their production or consumption planning. Inspired by that, a multi-period optimization model for determining real-time price and price forecast should also be developed. Uncertain parameters such as wind production and aggregated response of consumers and DERs to real-time electricity prices are approximated by a set of scenarios with their corresponding probabilities of occurrence. The TSO will use the following multi-period stochastic optimization model for determining the real-time price at the next time step $(t = 1)$ and price forecasts at time step $t(\\forall t = 2, \\ldots, N_t)$ for different possible scenarios. The TSO also determines the deployment of up and down regulating power at the next time step $(t = 1)$ and time step $t(\\forall t = 2, \\ldots, N_t)$ for all possible scenarios respectively. The objective function of the proposed model will then be the maximization of the expected social welfare throughout the study horizon, i.e., the minimization of the reserve deployment cost by the generators and DERs for providing balancing power plus wind spillage cost minus the utility losses of the consumers. As shown in (14) at the bottom of the page, the objective function includes two items. The ﬁrst item represents the corresponding cost at next time step $(t = 1)$, which is the same as (4). The second item represents the expected cost incurred from time step $t = 2$ to time step $t = N_t$. The objective function (14) is subject to constraints (2), (4)–(13) and following constraints:"},{"evidence_id":"v141-b-g02-ev-24","location":{"location_id":"src-da8e4e26d6-p07-c2r3__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"ial me (15) he ost ve ng rm the (16) al- lly (17)","equation_id":"Eq. (15)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,t,s)} = P^{G,D}_{g} + P^{G,UR}_{(g,t,s)} - P^{G,DR}_{(g,t,s)}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (15)\n$\\sum_{l}^{N_L} (P^{L}_{(l,t,s)} + \\Delta P^{L}_{(l,t,s)} - L^{Shed}_{(l,t,s)}) - \\sum_{g}^{N_G} P^{G}_{(g,t,s)} - \\sum_{d}^{N_{DER}} (P^{DER}_{(d,t,s)} + \\Delta P^{DER}_{(d,t,s)}) - \\sum_{w}^{N_W} (P^{W}_{(w,t,s)} - W^{Spill}_{(w,t,s)}) = 0, \\forall t = 2, \\ldots, N_t, \\forall s$  (16)\n$0 \\le P^{G,UR}_{(g,t,s)} \\le \\overline{P^{G,UR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (17)"},{"evidence_id":"v141-b-g02-ev-25","location":{"location_id":"src-da8e4e26d6-p08-c1r1__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"DING et al.: REAL-TIME MARKET CONCEPT ARCHITECTURE (18) (19) (20) (21) (22)","equation_id":"Eq. (18)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"$0 \\le P^{G,DR}_{(g,t,s)} \\le \\overline{P^{G,DR}_{g}}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (18)\n$P^{G}_{(g,t-1,s)} - DR_{g} \\le P^{G}_{(g,t,s)} \\le P^{G}_{(g,t-1,s)} + UR_{g}, \\forall g, \\forall t = 2, \\ldots, N_t, \\forall s$  (19)\n$-\\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (20)\n$\\alpha_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)} = \\lambda^{R}_{(t,s)} - \\lambda^{D}, \\forall d, \\forall t = 2, \\ldots, N_t, \\forall s$  (21)\n$P^{L,min}_{(l,t)} \\le P^{L}_{(l,t)} + \\Delta P^{L}_{(l,t,s)} \\le P^{L,max}_{(l,t)}, \\forall l, \\forall t = 2, \\ldots, N_t, \\forall s$  (22)"},{"evidence_id":"v141-b-g02-ev-27","location":{"location_id":"src-da8e4e26d6-p08-c1r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"V. Quantitative Analyses","anchor_text":"p y price variations is described through (20) and (21) respectively. Likewise, the maximum and mini","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"unknown"},"source_text":"Equation (15) determines the total power produced by each large generating unit, time period and scenario. The power balance at each time period and scenario is enforced through (16). Constraints (17) and (18) limit the maximum deployment of up and down regulating power at each time period and scenario. The generating unit ramps bound the power generated at each time period and scenario through constraint (19). The response of consumers and DERs to real-time electricity price variations is described through (20) and (21) respectively. Likewise, the maximum and minimum changes of the consumers and DER's are imposed through constraints (22) and (23). Constraints (24) and (25) are positive variable declarations. By solving the above optimization problem, we can obtain real time prices, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power at each time period for different scenarios."},{"evidence_id":"v141-b-g02-ev-19","location":{"location_id":"src-da8e4e26d6-p06-c2r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"The objective function (3), shown at the bottom of the page, aims to minimize the regulating power c","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"$P^{G}_{(g,1)} = P^{G,D}_{g} + P^{G,UR}_{(g,1)} - P^{G,DR}_{(g,1)}, \\forall g$  (4)\n$0 \\le P^{G,UR}_{(g,1)} \\le \\overline{P^{G,UR}_{g}}, \\forall g$  (5)\n$0 \\le P^{G,DR}_{(g,1)} \\le \\overline{P^{G,DR}_{g}}, \\forall g$  (6)\n$P^{G}_{(g,0)} - DR_{g} \\le P^{G}_{(g,1)} \\le P^{G}_{(g,0)} + UR_{g}, \\forall g$  (7)"},{"evidence_id":"v141-b-g01-ev04","location":{"location_id":"src-da8e4e26d6-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"NOMENCLATURE","anchor_text":"Number of wind farms op- on- Number of scenarios to Constants ets ow Scheduled generated power of un","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Constants: P^{G,D}_{g} Scheduled generated power of unit g in the day-ahead market (MW); \\bar{P}^{G,UR}_{g} Up-regulating power offered by unit g (MW); \\bar{P}^{G,DR}_{g} Down-regulating power offered by unit g (MW); \\lambda^{G,UR}_{g} Bidding cost of electricity for up-regulation of unit g (euros/MWh); \\lambda^{G,DR}_{g} Bidding cost of electricity for down-regulation of unit g (euros/MWh); V^{LOL}_{l} Value of load shed corresponding to load l (euros/MWh); V^{spill}_{w} Value of wind spillage of wind farm w (euros/MWh); UR_{g} Up-ramp of generating unit g (MW/h); DR_{g} Down-ramp of generating unit g (MW/h)."}]},{"constraint_id":"v141-c-R003-C007","kind":"mathematical","role":"supporting","statement":"The regulating-power cost term of the single-period and multi-period social-welfare objectives uses the submitted up- and down-regulating bid prices as coefficients.","expression":"Single-period objective term (3): sum_g (P^{G,UR}_{(g,1)} * λ^{G,UR}_g - P^{G,DR}_{(g,1)} * λ^{G,DR}_g)\nMulti-period objective term (14): sum_g (P^{G,UR}_{(g,1)} * λ^{G,UR}_g - P^{G,DR}_{(g,1)} * λ^{G,DR}_g) + sum_s sum_{t=2}^{N_t} π_s * sum_g (P^{G,UR}_{(g,t,s)} * λ^{G,UR}_g - P^{G,DR}_{(g,t,s)} * λ^{G,DR}_g)","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R003-x-PGUR","v141-c-R003-x-PGDR"],"parameter_refs":["v141-c-R003-theta-LAMBDA-GUR","v141-c-R003-theta-LAMBDA-GDR"],"evidence_ids":["v141-b-g02-ev-18","v141-b-g02-ev-23","v141-b-g02-ev-21","v141-b-g01-ev31"],"ref":"08-real_time_prices::v141-c-R003::v141-c-R003-C007","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-ev-18","location":{"location_id":"src-da8e4e26d6-p06-c2r4__v141-a-M01-clearing","page":6,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"(5) (6) (7) (3) wnloaded on October 14,2026 at 08:46:10 UTC from IEEE Xplore. Restrictions apply.","equation_id":"Eq. (3)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{DER}_{(d,1)}, L^{Shed}_{(l,1)}, W^{Spill}_{(w,1)}, \\lambda^{R}_{1}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\}$  (3)"},{"evidence_id":"v141-b-g02-ev-23","location":{"location_id":"src-da8e4e26d6-p07-c2r4__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-B. Real-Time Price Settlement and Forecast Model","anchor_text":"(14) wnloaded on October 14,2026 at 08:46:10 UTC from IEEE Xplore. Restrictions apply.","equation_id":"Eq. (14)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"$\\text{Minimize}_{P^{G,UR}_{(g,1)}, P^{G,DR}_{(g,1)}, P^{G,UR}_{(g,t,s)}, P^{G,DR}_{(g,t,s)}, \\Delta P^{L}_{(l,1)}, \\Delta P^{L}_{(l,t,s)}, \\Delta P^{DER}_{(d,1)}, \\Delta P^{DER}_{(d,t,s)}, L^{Shed}_{(l,1)}, L^{Shed}_{(l,t,s)}, W^{Spill}_{(w,1)}, W^{Spill}_{(w,t,s)}, \\lambda^{R}_{1}, \\lambda^{R}_{(t,s)}} \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,1)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,1)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,1)} + \\frac{1}{2} \\alpha_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} \\cdot \\Delta P^{L}_{(l,1)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,1)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,1)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)} \\cdot \\Delta P^{DER}_{(d,1)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,1)} \\right\\} + \\sum_{s}^{N_S} \\sum_{t=2}^{N_t} \\pi_{s} \\cdot \\left\\{ \\sum_{g}^{N_G} (P^{G,UR}_{(g,t,s)} \\cdot \\lambda^{G,UR}_{g} - P^{G,DR}_{(g,t,s)} \\cdot \\lambda^{G,DR}_{g}) + \\sum_{l}^{N_L} (-\\lambda^{D} \\cdot \\Delta P^{L}_{(l,t,s)} + \\frac{1}{2} \\alpha_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} \\cdot \\Delta P^{L}_{(l,t,s)} + V^{LOL}_{1} \\cdot L^{Shed}_{(l,t,s)}) + \\sum_{d}^{N_{DER}} (\\lambda^{D} \\cdot \\Delta P^{DER}_{(d,t,s)} + \\frac{1}{2} \\alpha_{(d,1)} \\cdot \\Delta P^{DER}_{(d,t,s)} \\cdot \\Delta P^{DER}_{(d,t,s)}) + \\sum_{w}^{N_W} V^{Spill}_{w} \\cdot W^{Spill}_{(w,t,s)} \\right\\}$  (14)"},{"evidence_id":"v141-b-g02-ev-21","location":{"location_id":"src-da8e4e26d6-p07-c1r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV-A. Real-Time Price Settlement Model","anchor_text":"q ( ) p g y tim large unit at next time step . Note that this power is equal to the scheduled genera","equation_id":"Eq. (4)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Equation (4) determines the total power generated by each large unit at next time step $(t = 1)$. Note that this power is equal to the scheduled generation in the day-ahead market plus the deployment of regulating power at next time step. Constraints (5) and (6) limit the deployment of up and down regulating power according to the submitted bids. Ramp limits of large generating units are imposed through (7). Equations (8) and (9) determine the response of the ﬂexible demand and distributed energy resources, respectively, to a real-time price variation. Moreover, $\\alpha_{(l,1)}$ and $\\alpha_{(d,1)}$ correspond to the expected value of the response parameter to real-time electricity prices of the consumers and DERs, respectively. The maximum and minimum changes in the power consumed and produced by these prosumers are bounded through constraints (10) and (11). Finally, constraints (12), (13) are positive variable declarations. By solving the above optimization problem using commercial software like GAMS, we can obtain real time price at next time step $(t = 1)$, the response of ﬂexible response and DERs, the deployment of up and down regulating power, and marginal cost of activated up or down regulating power."},{"evidence_id":"v141-b-g01-ev31","location":{"location_id":"src-da8e4e26d6-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. OPTIMIZATION MODELS FOR REAL-TIME PRICE SETTLEMENT AND FORECAST","anchor_text":"tively small. With the increasing predication accuracy, the ratio can be gradually increased. In ord","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In order to implement the optimization model, the TSO has the following certain information: Cleared quantities to be generated and consumed as well as resulting prices from the day-ahead spot market. Up and down regulating bids (quantities and prices) submitted by generating units. Technical constraints of generating units such as maximum output and ramp limits. Moreover, the TSO has to make its decisions taking into consideration some uncertain parameters, such as: Power production of RESs, mainly wind production. Aggregated response of prosumers to real-time electricity prices. Taking into account both the known information and the uncertain parameters, the TSO has to determine: The deployment of up and down regulating power. The real-time electricity price and forecast to be sent to the market players."}]},{"constraint_id":"v141-c-R004-C001","kind":"procedural","role":"core","statement":"RP supply bids are submitted 45 minutes before the operational hour, preceding announcement of the real-time price signals during that hour. Scope: Current RP bid-submission deadlines and EcoGrid real-time price announcements for the same operational hour.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev30"],"ref":"08-real_time_prices::v141-c-R004::v141-c-R004-C001","source_rule_id":"v141-c-R004","evidence":[{"evidence_id":"v141-b-g01-ev30","location":{"location_id":"src-da8e4e26d6-p05-c1r4__v141-a-M02-participation","page":5,"printed_page":null,"section":"IV. OPTIMIZATION MODELS FOR REAL-TIME PRICE SETTLEMENT AND FORECAST","anchor_text":"market and the existing RP market can provide arbitrage oppor- ta tunities. It is possible that the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"exception"},"source_text":"To prevent price arbitrage between two markets, the TSO can set up market rules so that market players can only participate in only one market: RP market or real-time market. Specific market rules can be defined: The RP market addresses larger conventional generating units (above 10 MW). Only small prosumers e.g., households are subject to the general real-time price signal and participate in the real-time market. Moreover this problem would to a certain extent be mitigated by the current market rules: For participating in the RP market, the players (bulk physical suppliers) must submit their bids 45 mins before the operational hour. While real-time price signals are announced during the operational hour based on the system operational status, therefore it is not possible to use this information for create the bids in the RP market."}]}],"variables":[{"variable_id":"v141-c-R003-x-PGUR","symbol":"P^{G,UR}_{(g,t,s)}","meaning":"Up-regulating power of unit g deployed at time step t and scenario s.","kind":"operational","domain":"0 ≤ P^{G,UR}_{(g,t,s)} ≤ Pbar^{G,UR}_{g} (MW)","unit":"MW","indices":["g","t","s"],"evidence_ids":["v141-b-g01-ev07","v141-b-g02-ev-19","v141-b-g02-ev-24"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::x::v141-c-R003-x-PGUR"},{"variable_id":"v141-c-R003-x-PGDR","symbol":"P^{G,DR}_{(g,t,s)}","meaning":"Down-regulating power of unit g deployed at time step t and scenario s.","kind":"operational","domain":"0 ≤ P^{G,DR}_{(g,t,s)} ≤ Pbar^{G,DR}_{g} (MW)","unit":"MW","indices":["g","t","s"],"evidence_ids":["v141-b-g01-ev07","v141-b-g02-ev-19","v141-b-g02-ev-25"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::x::v141-c-R003-x-PGDR"}],"parameters":[{"parameter_id":"v141-c-R003-theta-PGUR-bar","symbol":"Pbar^{G,UR}_{g}","meaning":"Up-regulating power offered by unit g (submitted up-regulating bid quantity).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["g"],"evidence_ids":["v141-b-g01-ev04","v141-b-g02-ev-19","v141-b-g02-ev-24"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::theta::v141-c-R003-theta-PGUR-bar"},{"parameter_id":"v141-c-R003-theta-PGDR-bar","symbol":"Pbar^{G,DR}_{g}","meaning":"Down-regulating power offered by unit g (submitted down-regulating bid quantity).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["g"],"evidence_ids":["v141-b-g01-ev04","v141-b-g02-ev-19","v141-b-g02-ev-25"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::theta::v141-c-R003-theta-PGDR-bar"},{"parameter_id":"v141-c-R003-theta-LAMBDA-GUR","symbol":"λ^{G,UR}_{g}","meaning":"Bidding cost of electricity for up-regulation of unit g.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"euros/MWh","indices":["g"],"evidence_ids":["v141-b-g01-ev04","v141-b-g02-ev-18","v141-b-g02-ev-21"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::theta::v141-c-R003-theta-LAMBDA-GUR"},{"parameter_id":"v141-c-R003-theta-LAMBDA-GDR","symbol":"λ^{G,DR}_{g}","meaning":"Bidding cost of electricity for down-regulation of unit g.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"euros/MWh","indices":["g"],"evidence_ids":["v141-b-g01-ev04","v141-b-g02-ev-18","v141-b-g02-ev-21"],"source_rule_id":"v141-c-R003","declaration_ref":"08-real_time_prices::v141-c-R003::theta::v141-c-R003-theta-LAMBDA-GDR"}]}],"source_definitions":[{"unit_id":"08-real_time_prices::v141-a-M01::bidding.supply","stage":"L3","subtype":"scoped_supply_submission_rules","projection_status":"composite","target_definition":"This unit jointly contains two definitions: EcoGrid participants do not submit supply bids or schedules; the upward/downward regulation bid quantities and prices already submitted in the adjacent RP market serve as inputs to the TSO optimization. RP bids are submitted 45 minutes before the operating hour; their quantities set deployment upper limits, and their prices serve as regulation cost coefficients.","form_kind":"procedural","identity_fields":["Object one: EcoGrid participants' supply bids and schedules; rule: no submission required","Object two: RP upward/downward regulation bid quantities and prices; rule: after submission, they serve as optimization inputs","Output: a non-submission requirement and submitted supply information belonging to different market scopes"],"variation_fields":["EcoGrid participants respond autonomously to the current price.","RP bid quantities: Pbar^{G,UR}_g, Pbar^{G,DR}_g","RP bid prices: λ^{G,UR}_g, λ^{G,DR}_g","RP submission time: 45 minutes before the operating hour, earlier than the publication of the real-time price for that hour","The bids are used in single-period or multi-period scenario models; the downward-regulation bid price carries a negative sign in the original regulation cost term."],"constraint_refs":["08-real_time_prices::v141-c-R002::v141-c-R002-C001","08-real_time_prices::v141-c-R002::v141-c-R002-C002","08-real_time_prices::v141-c-R003::v141-c-R003-C001","08-real_time_prices::v141-c-R003::v141-c-R003-C002","08-real_time_prices::v141-c-R003::v141-c-R003-C007","08-real_time_prices::v141-c-R004::v141-c-R004-C001"],"paper_id":"08-real_time_prices","mechanism_id":"v141-a-M01","function":"bidding.supply","template_code":"PGR"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/76"});
